    "intro": "Five teenagers are looking for a part-time job. Read the descriptions of eight jobs (A–H) and decide which one would be the most suitable for each teenager.",
    "stem": "Which job would be the most suitable for each teenager?",
    "sections": [
     {
      "l": "A",
      "h": "Dog Walker",
      "t": "Do you love dogs? Our busy town needs people to walk dogs while their owners are at work. You choose your own hours, any day of the week, and you can walk one dog or several. We pay £8.50 an hour, and owners often give a little extra as a thank-you. You must be at least fourteen and live near the park. A short training session is included."
     },
     {
      "l": "B",
      "h": "Market Stall Helper",
      "t": "Help to sell fruit and vegetables on a busy stall at one of our local markets. You will put out the boxes, serve customers and give them their change. The work is outside, every Saturday from 8:30 to 1:30, and you will learn on the job, so no experience is needed. The pay is £7 an hour, and you can take home any fruit that is left over."
     },
     {
      "l": "C",
      "h": "Café Assistant",
      "t": "Our friendly café is run by a newly qualified chef and needs help after school from Monday to Friday, 4 to 8 pm. You will take orders, carry plates and wash cups. You must be at least sixteen, and previous experience is useful. The pay is £6.50 an hour, and you get a free meal at the end of every shift."
     },
     {
      "l": "D",
      "h": "Cinema Assistant",
      "t": "Work in a busy cinema and watch new films for free! You will check tickets, sell popcorn and help families find their seats. Shifts are in the evening, from 6 pm to 10 pm, three days a week. You must be sixteen or older and happy to work at weekends. The pay is £7 an hour, and the uniform is provided."
     },
     {
      "l": "E",
      "h": "Newspaper Delivery",
      "t": "Deliver newspapers to homes in your area before school. You start at 6 am and finish by 7:30, from Monday to Saturday, and you need your own bike. It is a good way to stay fit and learn to be on time. The pay is £5 an hour, with a bonus at Christmas. You must be at least fourteen. Waterproof bags are provided, and you will meet new people every morning."
     },
     {
      "l": "F",
      "h": "Animal Shelter Helper",
      "t": "Look after cats, dogs and rabbits at our animal shelter. You will clean cages, feed the animals and play with them. The hours are fixed: Saturdays and Sundays from 9 am to 1 pm. The pay is £8 an hour, and a vet explains how to treat the animals safely. You should be fifteen or older. No experience is needed, but you must love animals and be ready to get a little dirty."
     },
     {
      "l": "G",
      "h": "Sports Centre Helper",
      "t": "Our sports centre needs young people aged fifteen and over to put out equipment, clean changing rooms and help at children's classes. Hours are on Saturdays and Sundays, from 10 to 4. You need common sense and a love of sport. The pay is £6.50 an hour, and all helpers get a free swimming pass and can use the gym when it is quiet."
     },
     {
      "l": "H",
      "h": "Bookshop Assistant",
      "t": "This friendly bookshop is one of the last independent small businesses on our high street. We need a helper to arrange shelves, talk to customers and recommend books. Hours are Monday to Thursday, 4 to 6:30 pm, and the pay is £7 an hour. You must be at least fifteen. We would love someone who reads a lot and enjoys chatting to people."
     }
    ],
    "qs": [
     {
      "n": 1,
      "s": "Leo is fifteen and has never had a job. He would like to work only on Saturday mornings, because he plays in a match every Sunday. He also prefers working outside to being inside a building all day. He lives near the market and can walk there.",
      "a": "B",
      "w": "Leo wants no experience, Saturday mornings only and outdoor work. <b>B</b> is an outdoor stall on Saturdays from 8:30, and no experience is needed. <b>E</b> is outside and needs no experience, but it is every morning from Monday to Saturday at 6 am."
     },
     {
      "n": 2,
      "s": "Aisha is sixteen and loves being surrounded by books. She would like to work with customers face to face. She is busy at weekends with her family, so she can only work on weekdays after school. She enjoys talking and is good at helping people.",
      "a": "H",
      "w": "Aisha wants books, customers and weekdays only. <b>H</b> is a bookshop, with Monday to Thursday afternoons. <b>C</b> is also on weekdays after school and involves customers, but it is a café and has nothing to do with books."
     },
     {
      "n": 3,
      "s": "Marco adores animals and has two dogs of his own. His school timetable changes every week, so he wants to choose his own hours. He would also like to earn at least £8 an hour. He has already walked dogs for his neighbours, but never for pay.",
      "a": "A",
      "w": "Marco needs animals, hours he can choose and £8+ per hour. <b>A</b> lets you choose your own hours and pays £8.50. <b>F</b> pays £8 and is about animals, but the hours are fixed on Saturdays and Sundays."
     },
     {
      "n": 4,
      "s": "Sofia is sixteen and a real film fan. She would love a job where she can see new films for free. Her school finishes late on weekdays, so she can only start work after 6 pm. She likes to see what is new at the cinema.",
      "a": "D",
      "w": "Sofia needs films, free viewing and a start after 6 pm. <b>D</b> is a cinema job with free films and shifts from 6 pm. <b>C</b> is a job she could do in the evening too, but it is a café and offers only a free meal, not films."
     },
     {
      "n": 5,
      "s": "Ben is fifteen and plays sport every day. He would like a job connected with sport and would love to use a swimming pool for free. He is at school all week, so he can work only on weekends. He is strong and likes to be active.",
      "a": "G",
      "w": "Ben wants sport, free swimming and weekends only. <b>G</b> is at a sports centre on Saturdays and Sundays, with a free swimming pass. <b>F</b> is also on weekends only, but it is about animals and there is no swimming."
     }
    ]
