    "intro": "Five teenagers are looking for a place to eat. Read the descriptions of eight restaurants (A–H) and decide which one would be the most suitable for each teenager.",
    "stem": "Which restaurant would be the most suitable for each teenager?",
    "sections": [
     {
      "l": "A",
      "h": "Green Bowl",
      "t": "This lively vegan café serves huge bowls of rice, beans, vegetables and tasty sauces. Prices are low: most bowls cost between £5 and £7, and you will fill up easily. The café is open for lunch only, from 11:30 to 3, every day except Sunday. There are a few tables, but most people take their food to the park. Staff are friendly and speak English."
     },
     {
      "l": "B",
      "h": "Pizza Palace",
      "t": "A big, noisy restaurant with a special room for birthday parties. Children's menus and balloons are provided, and there is a clown on Saturday afternoons. Pizzas and ice creams are the main attractions, and a meal costs around £12 per person. The restaurant is open every day from noon until 10 pm, and it is close to the cinema. Booking is advisable at weekends."
     },
     {
      "l": "C",
      "h": "Noodle Express",
      "t": "Hot noodle soup in under ten minutes! Choose your noodles, your meat or vegetables and your sauce, and the cooks prepare everything in front of you. A bowl costs £5.50. You can eat at the long counter or take your meal away, and the restaurant stays open until midnight, which makes it a favourite after a film. The staff are quick and friendly."
     },
     {
      "l": "D",
      "h": "The Garden Café",
      "t": "This quiet café has tables under the trees and free wifi, so many students come here to read or study. Homemade soups, sandwiches and cakes are served all day, and prices are fair. On Friday evenings a guitarist plays soft music. It is open from 9 am to 8 pm, and you can stay as long as you like without feeling rushed."
     },
     {
      "l": "E",
      "h": "Sushi Corner",
      "t": "Take plates of sushi from a moving belt and pay according to the colour of the plate. The food is fresh and beautiful, but a full meal often costs more than £20. The restaurant is small, so it is a good idea to book a table. It is open in the evening only, from 6 to 10, and closed on Mondays."
     },
     {
      "l": "F",
      "h": "Burger Barn",
      "t": "The portions here are enormous, and you can refill your drink as often as you like. Friends often come in groups, and there is a long table for ten people. Brave eaters can take the bull by the horns and try our Giant Challenge: finish the biggest burger in town in half an hour and it is free. Open daily, noon to 10 pm."
     },
     {
      "l": "G",
      "h": "Bakery and Brunch",
      "t": "Our bakery sells warm bread, pastries and eggs every morning from 7 to 11:30. You can sit by the window and watch the street while you eat. A breakfast costs about £8, and there is no table service, so you order at the counter. The bakery is closed in the afternoon and evening. Fresh coffee and juice are also available."
     },
     {
      "l": "H",
      "h": "Home Kitchen",
      "t": "This family-run restaurant is one of the town's small businesses, and it serves traditional dishes from the owner's grandmother's recipes: stews, dumplings and fruit pies. The dining room has long tables, so it is ideal for large groups, and you can book for up to twelve people. Open from noon to 9 pm every day. Main courses cost between £9 and £13."
     }
    ],
    "qs": [
     {
      "n": 1,
      "s": "Lena has an important exam on Monday and wants somewhere calm to study for a few hours. She prefers to sit outside if the weather is nice, and she needs wifi on her laptop. She will stay for several hours and will have lunch there.",
      "a": "D",
      "w": "Lena wants a calm place, outdoor tables and wifi. <b>D</b> is a quiet café with tables under the trees and free wifi, and it serves soups and sandwiches all day. <b>G</b> has a window seat but it is indoors, and it closes at 11:30."
     },
     {
      "n": 2,
      "s": "Hugo is organising his grandfather's birthday and needs a table for ten people. His family likes old-fashioned food like their grandmother used to make. He would like a small family business rather than a big chain. He is fifteen and will make the booking himself.",
      "a": "H",
      "w": "Hugo wants a table for ten, traditional food and a small family business. <b>H</b> is family-run, serves recipes from the owner's grandmother and takes groups of up to twelve. <b>F</b> has a table for ten, but it serves burgers and is not a family business."
     },
     {
      "n": 3,
      "s": "Mia is a vegetarian who is trying to save money. She would like to spend no more than £8 on lunch, and she wants a big meal that will fill her up for the rest of the afternoon. She is fourteen and lives near the centre.",
      "a": "A",
      "w": "Mia needs vegetarian food, a price under £8 and a big meal. <b>A</b> is a vegan café with big bowls that cost £5 to £7. <b>C</b> is cheap (£5.50), but its noodles come with meat or vegetables and are not a vegetarian choice."
     },
     {
      "n": 4,
      "s": "Ravi is meeting his friends at the cinema at 9 pm, and he is hungry and in a hurry. He wants a quick meal that is ready within ten minutes, and he needs a place that is still open late.",
      "a": "C",
      "w": "Ravi wants a fast meal and late opening. <b>C</b> serves hot noodle soup in under ten minutes and stays open until midnight. <b>B</b> is close to the cinema and open until 10 pm, but it is slow, noisy and not quick."
     },
     {
      "n": 5,
      "s": "Oscar is training for a football match and is always starving. He is going out with eight friends and wants a place with very big portions where they can have a bit of fun, such as a challenge. He is always the loudest in the group.",
      "a": "F",
      "w": "Oscar wants huge portions, a group table and a challenge. <b>F</b> has enormous portions, a long table for ten and the Giant Challenge. <b>H</b> also welcomes large groups, but it has no challenge and its dishes are traditional, not huge."
     }
    ]
