    "text": "Last year I started a podcast at my school, and I still can't quite believe how many people listen to it. It began as a joke. My friend Tomás and I were waiting for the bus after football practice, and he said that we talked so much that someone should record us. I laughed, but that evening I borrowed my brother's microphone and tried it out.\n\nThe first episode was a disaster. I spoke too fast, a dog barked in the background, and I forgot the name of our headteacher. It was on the tip of my tongue, but it never came out. I wanted to delete everything. Tomás said we should send the recording to our English teacher, Ms Okafor, before we decided. She listened to all twenty minutes and then told us that the idea was good, but we needed a plan.\n\nHer advice was simple. Choose one topic for each episode, write down three questions, and always speak up, because a quiet voice sounds nervous. Tomás has the gift of the gab, so he found that easy, but I had to practise in front of the mirror. Several times I started again because I sounded like a robot reading a shopping list.\n\nOur podcast really kicked off when we interviewed the school cook about how she plans meals for six hundred students. We expected a boring chat, but she told funny stories about burnt rice and a famous day when the soup ran out. After that episode, students stopped us in the corridor to say they had listened on the way to school. Even some teachers started asking when the next one would be ready.\n\nNow we record every Thursday at lunchtime in the music room, which is quiet and has soft walls. Each month we also invite a small group of students to join us as guests and give their opinions. Being a panellist is harder than it looks, so we always ask everyone to be respectful and let others finish their sentences. Sometimes we disagree, but that makes the episodes more interesting.\n\nThe best part, though, is not the number of listeners. Before the podcast, I rarely put my hand up in class. Now I enjoy explaining my ideas, and I am not afraid of silence any more. Next year I would like to teach younger students how to make their own shows, because I think anyone with a phone and a good question can do it.",
