    "text": "When we moved to a fishing village on a cold northern coast, I was sure I would hate it. The sea was grey, the wind never stopped, and my old friends were hundreds of kilometres away. For the first month I felt down in the dumps and spent most evenings in my room.\n\nEverything changed because of a girl called Freya, who sat next to me in maths. She noticed that I never joined the group at lunch, and one day she said, \"Come to the beach on Saturday. We're going surfing.\" I told her I could not even swim well in warm water. She laughed and said that nobody in the village was born knowing how to surf.\n\nOn Saturday I showed up at the beach in a thick wetsuit, boots, gloves and a hat. The water was so cold that my face hurt. Freya's older brother, Callum, taught me to lie on the board and stand up in one movement. It sounds easy, but I fell off about fifty times. By the end of the morning my arms felt like jelly, and my legs hurt for several days afterwards. I could not imagine going back.\n\nBut the next weekend I did, and the one after that. Slowly I began to catch small waves. The others were far better than me, so at first I could hardly keep up with them. Still, they never made me feel stupid. Callum used to say that the best surfer in the water is the one who is having the most fun. That was a relief.\n\nThe first time I stood up and rode a wave all the way to the sand, I felt a happiness I can't describe. I shouted so loudly that a man walking his dog turned round. I had a sleepless night, not because I was worried, but because I was too excited to sleep.\n\nI still miss my old friends, and I still think the sea is far too cold. But I have learned that a place can change when you are brave enough to try something new. Next spring there is a small competition for beginners on our beach, and Freya says I should enter. I haven't decided yet, but I'm practising every weekend, just in case.",
