    "text": "I was seventeen when I got my first job in a restaurant. I had been cooking at home since I was ten, so I thought I was ready. On my first day the head chef, a tall woman called Marta, gave me a bucket of potatoes and a small knife. \"Peel these,\" she said. I peeled potatoes for six hours.\n\nI was disappointed, but I did not say anything. I watched the other cooks instead. The kitchen was hot, loud and very fast, and everybody seemed to know exactly what to do. Every few minutes someone shouted an order, and plates left the kitchen as if by magic. I realised that I knew nothing about cooking in a real restaurant.\n\nThe money was another problem. I earned very little, and my family lived far from the city, so I had to move out and rent a tiny room above a bakery. My uncle had once run up big debts to open a café that closed after a year, so I had no wish to take out a bank loan myself. After paying for the room and my bus ticket, I could hardly make ends meet. Some weeks I ate only bread and soup, which was far from a balanced diet.\n\nSlowly, things improved. After a month Marta let me prepare sauces. I also learned that she would take away any plate that was not perfect, even if the customer was waiting. At first this made me angry. Later I understood that she was protecting the name of the restaurant. She also taught me that fresh vegetables keep all their goodness, and that is why a simple dish can taste wonderful. I kept a notebook where I wrote down every recipe, crossing out my mistakes and starting again.\n\nThe biggest moment came in December. Two cooks were ill, and the restaurant was full of people celebrating before the holidays. Marta looked at me and said, \"You're doing the fish tonight.\" My hands were shaking, but I cooked forty portions without one plate coming back. She did not say well done. She just nodded. It was the best compliment I have ever had.\n\nYears later I still remember that nod. I now have my own small kitchen, and I tell young cooks what Marta told me without words: the first months are about learning to be patient. Nobody becomes a good chef by being in a hurry.",
