    "text": "My name is Nadia, I'm fifteen, and every Saturday morning I train a dog to find people who are lost. Most of my friends think it is strange, but for me it is the best part of the week. It all started when I was ten and my uncle brought home a young border collie called Pepper, who could not stop running after everything that moved.\n\nPepper was clever but wild. She ate shoes, dug up the garden and once ran away through the front door and disappeared for two hours. My uncle was ready to give her away, but I begged him to wait. A neighbour told us about a local group of volunteers who train search dogs, and we decided to go to their next meeting.\n\nThe group gets together every weekend in a forest outside town. When I first arrived, I was the youngest by about twenty years. Everyone was friendly, but the trainer, Mr Aldana, was very clear: dogs learn from people who are calm. \"If you are nervous, she will be nervous,\" he told me. That was hard, because I am nervous about nearly everything!\n\nThe training is a kind of game. Someone hides in the forest, and the dog has to find them by smell. When Pepper finds the person, she gets a toy and lots of praise. The first time she did it, I was so proud that I nearly cried. Now she can follow a smell across a river, and she works for hours without getting tired.\n\nLast March our group was called out because a boy of six with fair hair had wandered away from his football team's picnic. A rapid response is essential in these cases, so within twenty minutes ten of us were in the forest. Pepper found the boy asleep under a tree, cold but safe. I will never forget his mother's face.\n\nMr Aldana has now stepped down as leader after twenty years, and I am helping the new one. At fifteen I can join searches as long as an adult goes with me, and I am already studying first aid. When I am older, I want to be a vet. Pepper has taught me that being patient and calm can solve almost any problem.",
