    "text": "Hana Sato is fourteen and has just published her first book, a collection of short stories. She told us how she did it.\n\nQ: When did you start writing?\nA: When I was nine. I was ill for a month and my mother gave me a notebook so that I wouldn't be bored. I wrote a story about a cat who lives in a lighthouse. It wasn't good, but I loved it, and I haven't stopped since.\n\nQ: Why short stories and not a novel?\nA: A novel feels like climbing a mountain. A short story is more like a walk: you can finish it in an afternoon and see the result quickly. I also find it easier to keep one clear idea in my head from the beginning to the end.\n\nQ: Who is your target audience?\nA: People my age, mainly. I write about things that happen to us: moving house, losing a friend, the first day at a new school. A teacher read one of my stories and said it had a natural directness: I say things simply and clearly, and I don't use long, difficult words. I think that's the best compliment I've ever had, because I want my readers to enjoy the story, not to open a dictionary every few lines.\n\nQ: How did the book get published?\nA: My school has a small printing project. A group of older students helped me to edit and design it. We printed fifty copies and sold them at the school fair, and all of them were gone in an hour. Then a local bookshop asked for twenty more, and the owner put them in the window next to some famous authors. I could hardly believe it.\n\nQ: Did anything surprise you?\nA: How much rewriting there is. The first version of every story is terrible. I rewrite each one five or six times. At first I hated that, but now I think it's where the real work happens.\n\nQ: What advice would you give to other young writers?\nA: Don't wait for the perfect idea. Start writing, even if the first draft is bad, because you can't improve a blank page. And don't show your work only to your family. They always say it's wonderful! Ask a friend who will tell you the truth, kindly.",
