    "text": "The first bicycles looked very different from the ones we ride today. In 1817 a German inventor built a wooden machine with no pedals, so riders had to [[1]] themselves along the ground with their feet. Later models had metal wheels, but they were so hard that people called them 'boneshakers'. Wooden wheels also [[2]] quickly, so makers started to use rubber. When the safety bicycle arrived, its chain made it faster and easier to ride, and prices [[3]] sharply as more factories began to build it. Cycling clubs gave young people the chance to make [[4]] friends, and long races got a lot of [[5]] in the newspapers. [[6]] 1900, millions of people owned a bicycle, and cities had to build special roads for them.",
