    "text": "Last year our school turned an empty corner of the playground into a garden. A teacher asked for volunteers, and about twenty students offered to [[1]] behind after lessons on Tuesdays. At first we had to take down an old fence, and then we dug the soil and planted beans, carrots and lettuces. We learned many [[2]] skills, such as using tools and building a small greenhouse. Every week we [[3]] down what had grown and what the insects had damaged. Snails and birds sometimes [[4]] up the young plants, so we made a net to protect them. The garden has also taught us a lot about the [[5]] world, because we now see how bees and worms help plants to grow. [[6]] the work is hard, we all agree it is worth it.",
