    "text": "Penguins are birds that cannot fly, but they are brilliant swimmers. They dive deep into the sea to catch fish, and they can stay under the water for a long time. Thick, waterproof feathers cover their bodies, and under the skin there is a layer of fat that [[1]] them warm in freezing water. On ice, they sometimes lie on their stomachs and slide, which is much quicker than walking. Last July the temperature [[2]] sharply to minus fifty, and emperor penguins stood together in huge groups. After weeks without food, a male penguin may be utterly [[3]]. Young penguins [[4]] out loud cries when they are hungry. They are [[5]] and playful, and when a seal comes near, they run for their [[6]], away from the edge of the ice.",
