    "text": "Marco Silva grew up in a small town by the sea. His family had very little money, so he made a ball from old socks and played in the street [[1]] dark. Many boys in his team [[2]] out when school became difficult, but Marco decided to carry on, no matter what. His coach said, 'You are small, but you have [[3]] feelings for the game, and that is what counts.' Sometimes Marco felt [[4]] down after a bad week, yet he never stopped training. At fifteen, a big club offered him a place in its youth academy. His mother was worried about the move, and he said, 'Fair [[5]], Mum, but I must try.' Years later, he said that he [[6]] everything to his first coach.",
