    "text": "Mountain rescue teams are groups of volunteers who help people in trouble in the hills. Many walkers like to go off the beaten track, but this can be dangerous if the weather changes quickly. When someone calls for help, the team members [[1]] by and wait for a message from the police. First, a volunteer must [[2]] on to a special computer system to see the walker's position on a map. Then the team drives as close as possible and [[3]] up the mountain on foot. A rescuer sometimes [[4]] out a loud shout so that a lost person can find them in the fog. [[5]] the weather is terrible, the team goes out to search. Most people they find are cold and utterly exhausted, so the team gives them hot drinks and warm clothes. The volunteers are not paid, so they do the work [[6]] their free time.",
