    "text": "Many video games are set in the past, and teachers are starting to use them in history lessons. In one game, players build an ancient city and have to [[1]] decisions about food, water and trade. The graphics work like visual [[2]], because students can see how people lived. Of course, a game is not a textbook, so students must still look for [[3]] evidence from real sources, such as letters and maps. The [[4]] idea of one popular game is that every choice has a result, so players learn to think about cause and effect. Some games even come with a [[5]] written by historians, which explains what is true and what is invented. One teacher says that after a lesson with the game, [[6]] students ask to read more about the period.",
