    "text": "Last weekend I visited my aunt, who lives in a small town in the mountains. She picked me [[1]] from the station on Friday evening. I was afraid it would be boring, but I soon found [[2]] that there was plenty to do. The [[3]] people were friendly, and everyone seemed to know each other. A market [[4]] place every Saturday in the main square, and my aunt took me there early. I bought some honey and a woollen hat. In the afternoon my cousins wanted to go home, but I decided to [[5]] behind and help my aunt in her garden. I did not expect to enjoy it so much. When I got home, I was already [[6]] forward to my next visit.",
