    "text": "Last Thursday our class went to the science museum, [[1]] we spent the whole day. The bus journey was long, but nobody complained because we were looking forward to the visit. First, a guide showed us [[2]] a rocket engine works. Then we had lunch in the garden, and some students ate far [[3]] much sugar, which was a mistake! In the afternoon we [[4]] allowed to touch the exhibits in the electricity room. My hair stood up when I touched a special ball! I was so excited that I did not want to leave, so I stayed behind to take one more photo [[5]] the others went back to the bus. My teacher was not angry. She said she would have done the same [[6]] she had been in my place.",
