    "text": "My mother works late, so last year I decided to learn to cook. At first I was hopeless. I once put salt in a cake instead of sugar, and nobody [[1]] eat it! But my grandmother, [[2]] has cooked all her life, taught me some simple rules. 'Read the recipe twice before you start,' she said, 'and always put things back [[3]] you have used them.' Now I can make a good soup and a few pasta dishes. I try to follow a balanced diet, and I have cut [[4]] on fast food. My friends are surprised [[5]] how much I enjoy it. My little brother is the best judge: if he asks for more, I know it is good, but if he [[6]] not finish his plate, I have to try again.",
