    "text": "Dear Mum and Dad, We arrived at the camp on Monday, and I am having a great time. The weather is better [[1]] I expected, so we spend most of the day outside. Our group leader, Tom, [[2]] comes from a small town like ours, is really funny. Yesterday we had to deal with a problem: it started to rain heavily while we [[3]] cooking dinner on a campfire. We put the tent up quickly and finished eating inside. Last night I could not sleep, [[4]] I was homesick, but today I feel fine. There is nothing to worry [[5]]. The only problem is that I have lost my torch. If you find it at home, please send it, because I need it [[6]] reading at night. Love, Ana",
